// Dispatch brain: session window, supplier ranking, acceptance locking.
// State lives in workflow static data so it survives an n8n restart.
const store = $getWorkflowStaticData('global');
store.jobs = store.jobs || {};
store.offers = store.offers || [];
store.inbound = store.inbound || {};

const DAY = 24 * 60 * 60 * 1000;
const OFFER_TIMEOUT_MS = 5 * 60 * 1000;
const now = Date.now();

// Suppliers would normally come from a Google Sheet. Kept inline so the
// workflow runs before the Sheet credential exists.
const SUPPLIERS = [
  // Demo supplier points at the number registered on the Meta test number,
  // so the outbound leg is observable. Real deployments read this from a sheet.
  { id: 'sup-1', name: 'Highway Tyres', phone: '<RECIPIENT_MSISDN>', km: 8.2 },
  { id: 'sup-2', name: 'N1 Truck Assist', phone: '27820001002', km: 14.7 },
  { id: 'sup-3', name: 'Midrand Fitment', phone: '27820001003', km: 31.5 },
];

const body = $input.first().json.body || $input.first().json;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { action: 'ignore', reason: 'no message in payload' } }];
}

const from = message.from;
const text = (message.text?.body || '').trim();
store.inbound[from] = now;                       // opens this contact's 24h window

// A supplier replying YES <reference> accepts the job.
const accept = text.match(/^\s*(yes|ya|accept|ambil)\s+(\S+)/i);
if (accept) {
  const reference = accept[2].toUpperCase();
  const job = Object.values(store.jobs).find(j => j.reference === reference);
  const supplier = SUPPLIERS.find(s => s.phone === from);

  if (!job) {
    return [{ json: { action: 'reply', to: from, windowOpen: true,
                      text: `No open job found for ${reference}.` } }];
  }
  if (job.assignedSupplierId) {
    // First acceptance already won. This is the idempotent branch.
    const already = job.assignedSupplierId === supplier?.id;
    return [{ json: { action: 'reply', to: from, windowOpen: true, jobId: job.id,
                      outcome: already ? 'assigned' : 'already_assigned',
                      text: already
                        ? 'You already have this job. Please send an ETA.'
                        : 'This job is already assigned to another supplier. No action needed.' } }];
  }

  job.assignedSupplierId = supplier?.id || from;
  job.status = 'assigned';
  job.assignedAt = now;
  store.offers.forEach(o => { if (o.jobId === job.id) o.resolved = true; });

  return [{ json: { action: 'assign', to: from, windowOpen: true, jobId: job.id,
                    reference: job.reference, outcome: 'assigned',
                    text: 'Job assigned to you. Please proceed and send an ETA.',
                    clientPhone: job.clientPhone } }];
}

// Anything else from a new contact is treated as a breakdown report.
const reference = 'JOB' + String(Object.keys(store.jobs).length + 1).padStart(4, '0');
const job = {
  id: reference, reference, detail: text, clientPhone: from,
  status: 'pending', createdAt: now, triedSupplierIds: [], assignedSupplierId: null,
};
store.jobs[reference] = job;

const nextSupplier = SUPPLIERS[0];
job.triedSupplierIds.push(nextSupplier.id);
job.status = 'offered';
store.offers.push({ jobId: job.id, supplierId: nextSupplier.id,
                    expiresAt: now + OFFER_TIMEOUT_MS, resolved: false });

// Window check decides free-form vs approved template for the supplier message.
const supplierLastInbound = store.inbound[nextSupplier.phone] || 0;
const supplierWindowOpen = (now - supplierLastInbound) <= DAY;

return [{
  json: {
    action: 'dispatch',
    jobId: job.id,
    reference,
    detail: text,
    clientPhone: from,
    clientWindowOpen: true,
    supplier: nextSupplier,
    supplierWindowOpen,
    supplierMessageType: supplierWindowOpen ? 'text' : 'template',
    clientText: `Got it. Reference ${reference}. Finding the closest fitment now.`,
  },
}];

// Meta webhook verification handshake.
// Echo hub.challenge back verbatim, but only when the verify token matches.
//
// The token is a constant rather than $env because n8n ships
// N8N_BLOCK_ENV_ACCESS_IN_NODE=true, which denies $env inside Code nodes.
// This value only proves the endpoint is ours during Meta's one-time
// handshake. It grants no access to anything.
const EXPECTED = 'SET_YOUR_OWN_VERIFY_TOKEN';

const query = $input.first().json.query || {};

if (query['hub.mode'] === 'subscribe' && query['hub.verify_token'] === EXPECTED) {
  return [{ json: { ok: true, challenge: query['hub.challenge'] } }];
}
return [{ json: { ok: false, challenge: 'verification failed' } }];
